import{_ as n,a0 as p,w as d,s,ao as l,I as o,x as e,a1 as r,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const A=JSON.parse('{"title":"Attic——删除重复数据的备份程序 | LCTT x X-CMD","titleTemplate":false,"description":"Attic——删除重复数据的备份程序 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Attic——删除重复数据的备份程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Attic——删除重复数据的备份程序 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141219 Attic--Deduplicating backup program","title":"Attic——删除重复数据的备份程序","tag":"201412","desc":""},"relativePath":"201412/20141219 Attic--Deduplicating backup program.md","filePath":"[post].md"}'),u={name:"201412/20141219 Attic--Deduplicating backup program.md"};function c(m,t,h,b,f,x){const a=p("Link");return d(),s("div",null,[t[16]||(t[16]=l(`<h1 id="attic——删除重复数据的备份程序" tabindex="-1">Attic——删除重复数据的备份程序 <a class="header-anchor" href="#attic——删除重复数据的备份程序" aria-label="Permalink to “Attic——删除重复数据的备份程序”">​</a></h1><p>Attic是一个Python写的删除重复数据的备份程序，其主要目标是提供一种高效安全的数据备份方式。重复数据消除技术的使用使得Attic适用于日常备份，因为它可以只存储那些修改过的数据。</p><h3 id="attic特性" tabindex="-1">Attic特性 <a class="header-anchor" href="#attic特性" aria-label="Permalink to “Attic特性”">​</a></h3><h4 id="空间高效存储" tabindex="-1">空间高效存储 <a class="header-anchor" href="#空间高效存储" aria-label="Permalink to “空间高效存储”">​</a></h4><p>可变块大小重复数据消除技术用于减少检测到的冗余数据存储字节数量。每个文件被分割成若干可变长度组块，只有那些从没见过的组合块会被压缩并添加到仓库中。</p><h4 id="可选数据加密" tabindex="-1">可选数据加密 <a class="header-anchor" href="#可选数据加密" aria-label="Permalink to “可选数据加密”">​</a></h4><p>所有数据可以使用256位AES加密进行保护，并使用HMAC-SHA256验证数据完整性和真实性。</p><h4 id="离场备份" tabindex="-1">离场备份 <a class="header-anchor" href="#离场备份" aria-label="Permalink to “离场备份”">​</a></h4><p>Attic可以通过SSH将数据存储到安装有Attic的远程主机上。</p><h4 id="备份可作为文件系统挂载" tabindex="-1">备份可作为文件系统挂载 <a class="header-anchor" href="#备份可作为文件系统挂载" aria-label="Permalink to “备份可作为文件系统挂载”">​</a></h4><p>备份归档可作为用户空间文件系统挂载，用于便捷地验证和恢复备份。</p><h4 id="安装attic到ubuntu-14-10" tabindex="-1">安装attic到ubuntu 14.10 <a class="header-anchor" href="#安装attic到ubuntu-14-10" aria-label="Permalink to “安装attic到ubuntu 14.10”">​</a></h4><p>打开终端并运行以下命令</p><pre><code>sudo apt-get install attic
</code></pre><h3 id="使用attic" tabindex="-1">使用Attic <a class="header-anchor" href="#使用attic" aria-label="Permalink to “使用Attic”">​</a></h3><h4 id="手把手实例教学" tabindex="-1">手把手实例教学 <a class="header-anchor" href="#手把手实例教学" aria-label="Permalink to “手把手实例教学”">​</a></h4><p>在进行备份之前，首先要对仓库进行初始化：</p><pre><code>$ attic init /somewhere/my-repository.attic
</code></pre><p>将~/src和~/Documents目录备份到名为Monday的归档：</p><pre><code>$ attic create /somwhere/my-repository.attic::Monday ~/src ~/Documents
</code></pre><p>第二天创建一个新的名为Tuesday的归档：</p><pre><code>$ attic create --stats /somwhere/my-repository.attic::Tuesday ~/src ~/Documents
</code></pre><p>该备份将更快些，也更小些，因为只有之前从没见过的新数据会被存储。--stats选项会让Attic输出关于新创建的归档的统计数据，比如唯一数据（不和其它归档共享）的数量：</p><pre><code>归档名：Tuesday
归档指纹：387a5e3f9b0e792e91ce87134b0f4bfe17677d9248cb5337f3fbf3a8e157942a
开始时间： Tue Mar 25 12:00:10 2014
结束时间： Tue Mar 25 12:00:10 2014
持续时间： 0.08 seconds
文件数量： 358
        最初大小    压缩后大小  重复数据删除后大小
本归档： 57.16 MB    46.78 MB    151.67 kB
所有归档：114.02 MB  93.46 MB    44.81 MB
</code></pre><p>列出仓库中所有归档：</p><pre><code>$ attic list /somewhere/my-repository.attic

Monday Mon Mar 24 11:59:35 2014
Tuesday Tue Mar 25 12:00:10 2014
</code></pre><p>列出Monday归档的内容：</p><pre><code>$ attic list /somewhere/my-repository.attic::Monday

drwxr-xr-x user group 0 Jan 06 15:22 home/user/Documents
-rw-r--r-- user group 7961 Nov 17 2012 home/user/Documents/Important.doc
</code></pre><p>恢复Monday归档：</p><pre><code>$ attic extract /somwhere/my-repository.attic::Monday
</code></pre><p>通过手动删除Monday归档恢复磁盘空间：</p><pre><code>$ attic delete /somwhere/my-backup.attic::Monday
</code></pre>`,32)),o("p",null,[t[1]||(t[1]=e("详情请查阅",-1)),r(a,{href:"https://attic-backup.org/index.html"},{default:i(()=>[...t[0]||(t[0]=[e("Attic文档",-1)])]),_:1}),t[2]||(t[2]=e("。",-1))]),t[17]||(t[17]=o("hr",null,null,-1)),o("p",null,[t[4]||(t[4]=e("via: ",-1)),r(a,{href:"http://www.ubuntugeek.com/attic-deduplicating-backup-program.html"},{default:i(()=>[...t[3]||(t[3]=[e("http://www.ubuntugeek.com/attic-deduplicating-backup-program.html",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=e("作者：",-1)),r(a,{href:"http://www.ubuntugeek.com/author/ubuntufix"},{default:i(()=>[...t[5]||(t[5]=[e("ruchi",-1)])]),_:1}),t[9]||(t[9]=e(" 译者：",-1)),r(a,{href:"https://github.com/GOLinux"},{default:i(()=>[...t[6]||(t[6]=[e("GOLinux",-1)])]),_:1}),t[10]||(t[10]=e(" 校对：",-1)),r(a,{href:"https://github.com/wxy"},{default:i(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[13]||(t[13]=e("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原创翻译，",-1)),r(a,{href:"http://linux.cn/"},{default:i(()=>[...t[12]||(t[12]=[e("Linux中国",-1)])]),_:1}),t[15]||(t[15]=e(" 荣誉推出",-1))])])}const g=n(u,[["render",c]]);export{A as __pageData,g as default};
